effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     // #define COUNT 20.        
     #define SF 1./min(acScreenSize.x,acScreenSize.y)
     #define SS(l,s) smoothstep(SF,-SF,l-s)
     #define hue(h) clamp( abs( fract(h + vec4(3,2,1,0)/3.) * 6. - 3.) -1. , 0., 1.)

     // Original noise code from https://www.shadertoy.com/view/4sc3z2
     #define MOD3 vec3(.1031,.11369,.13787)

     vec3 hash33(vec3 p3)
     {
     	p3 = fract(p3 * MOD3);
         p3 += dot(p3, p3.yxz+19.19);
         return -1.0 + 2.0 * fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
     }

     float simplex_noise(vec3 p)
     {
         const float K1 = 0.333333333;
         const float K2 = 0.166666667;

         vec3 i = floor(p + (p.x + p.y + p.z) * K1);
         vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);

         vec3 e = step(vec3(0.0), d0 - d0.yzx);
     	vec3 i1 = e * (1.0 - e.zxy);
     	vec3 i2 = 1.0 - e.zxy * (1.0 - e);

         vec3 d1 = d0 - (i1 - 1.0 * K2);
         vec3 d2 = d0 - (i2 - 2.0 * K2);
         vec3 d3 = d0 - (1.0 - 3.0 * K2);

         vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);
         vec4 n = h * h * h * h * vec4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + 1.0)));

         return dot(vec4(31.316), n);
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((180.0+angle)*0.0174533);
     TanRyu += vec2((0.0-position.x), (250.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;

         float m = 0.;
         float t = PROGRESS;
         vec3 col;
         for(float i=COUNT; i>=0.; i-=1.){
             float edge = simplex_noise(vec3(uv * vec2(2., 0.) + vec2(0, t + i*.15), 1.))*.2 + (.5/COUNT)*i + .25;
             float mi = SS(edge, uv.y) - SS(edge + .005, uv.y);        
             m *= SS(edge, uv.y+.015);
             m += mi;        

             if(mi > 0.){ col = hue(i/COUNT).rgb; }
         }           

         col = mix(color1.rgb, col, m);

         fragColor = vec4(col,1.0);
         vec4 FColor = vec4(col,color1.a);
         // if(invert) { fragColor = 1.-fragColor; FColor = 1.-FColor; }

 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    vec4 xnxx = mix(texColorX,gradmap,alpha);

 	    vec4 factor = colorfull? mix(texColorX,fragColor,1.0) : mix(texColorX,xnxx,1.0);
 	    // if(invert) { factor = 1.-factor; }

     vec4 resultfinal;
       if( blendMode==0 ) {
         vec4 fNorm = colorfull? FColor : factor;
         resultfinal = (fNorm * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = max(factor, texColor) * texColor.a; }
         // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         vec4 fNorm = colorfull? FColor : factor;
         resultfinal = newLayer(texColor, fNorm*hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
